 if(kind==='blade'||kind==='shadow'||kind==='claw'){for(let i=0;i<3;i++)spawn('vx-blade',x+(i-1)*9,y+(i-1)*9,null,{'--angle':(kind==='claw'?60:kind==='shadow'?-65:-30)+i*20+'deg'});return}
 if(kind==='shield'){spawn('vx-shield');spawn('vx-ring');return}
